def table(df):return '<div class="scroll">'+df.to_html(index=False,border=0,na_rep='—',float_format=lambda x:f'{x:,.2f}',escape=True)+'</div>'
def image(p):return '<img alt="Original versus funding-aware research results" src="data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()+'">'
def select(df,arm=None,cost='desk',period='2022-25',delay=1):
    q=(df.cost==cost)&(df.period==period)&(df.delay==delay)
    if arm is not None:q&=df.arm==arm
    return df[q]

old=select(s,'S01').iloc[0];new=select(s,'S01F').iloc[0];pair=select(pairs,'S01F').iloc[0];bridge=select(bridges,'S01F').iloc[0]
def annual(cost):
    a=s[(s.arm=='S01')&(s.cost==cost)&(s.delay==1)].set_index('period');n=s[(s.arm=='S01F')&(s.cost==cost)&(s.delay==1)].set_index('period')
    out=[]
    for y in periods:
        x,z=a.loc[y],n.loc[y];out.append({'Period':y,'Original trades':int(x.trades),'New trades':int(z.trades),'Original R':x.net_R,'New R':z.net_R,'Change R':z.net_R-x.net_R,'Original net USDT':x.net,'New net USDT':z.net,'New mean trade %':z.mean_net_pct,'New PF':z.profit_factor})
    return pd.DataFrame(out)

